ui/controls.py.css:
/* libadwaita widgets (switches, sliders, suggested buttons in Adw rows)
   follow Sonata's accent colour too */
@define-color accent_bg_color %(accent)s;
@define-color accent_color %(accent)s;
@define-color accent_fg_color %(label_on_accent)s;

/* push button */
button.sonata-button {
  min-height: %(control_h)s; min-width: 64px; padding: 0 12px;
  border-radius: %(r_button)s; border: none;
  font-family: %(font)s; font-size: %(text_body)s; font-weight: 400;
  color: %(label)s; background: %(control_bg)s;
  box-shadow: 0 0 0 0.5px %(hairline)s, %(shadow_control)s;
  transition: background-color %(t_press)s ease-out;
}
button.sonata-button:active { background: %(control_pressed)s; }
button.sonata-button.default { color: %(label_on_accent)s;
  background: linear-gradient(to bottom, alpha(%(accent)s, 0.92), %(accent)s); }
button.sonata-button.default:active { background: %(accent_selected)s; }
button.sonata-button.destructive { color: %(destructive)s; }
button.sonata-button:disabled { color: %(label_tertiary)s; box-shadow: 0 0 0 0.5px %(separator)s; }

/* pop-up button (Gtk.DropDown) with the Big Sur accent chevron cap */
dropdown.sonata-popup > button {
  min-height: %(control_h)s; padding: 0 2px 0 9px; border-radius: %(r_button)s; border: none;
  font-family: %(font)s; font-size: %(text_body)s;
  color: %(label)s; background: %(control_bg)s;
  box-shadow: 0 0 0 0.5px %(hairline)s, %(shadow_control)s;
}
dropdown.sonata-popup > button > box { border-spacing: 8px; }
dropdown.sonata-popup > button label { font-weight: 400; }
dropdown.sonata-popup > button arrow {
  min-width: 16px; min-height: 16px; margin: 3px 0; border-radius: 4px; -gtk-icon-size: 12px;
  -gtk-icon-source: -gtk-icontheme("sonata-updown-symbolic");
  color: %(label_on_accent)s; background: %(accent)s;
}
dropdown.sonata-popup popover > contents {
  padding: 5px; border-radius: %(r_menu)s;
  font-family: %(font)s; font-size: %(text_body)s;
  color: %(label)s; background-color: %(panel_material)s;     /* the menus' glass (Vini) */
  box-shadow: 0 0 0 0.5px %(hairline)s, inset 0 0 0 0.5px %(highlight)s, %(shadow_menu)s;
}
dropdown.sonata-popup popover listview { background: none; }
dropdown.sonata-popup popover row {
  min-height: %(control_h)s; padding: 0 8px; border-radius: %(r_menu_row)s; background: none;
}
dropdown.sonata-popup popover row:hover, dropdown.sonata-popup popover row:selected {
  background-color: %(accent_selected)s; color: %(label_on_accent)s;
}

/* switch */
switch.sonata-switch {
  min-width: %(switch_w)s; min-height: %(switch_h)s; padding: 0; border: none;
  border-radius: 99px; background: %(control_off)s;
  box-shadow: inset 0 0 0 0.5px %(separator)s;
  transition: background-color %(t_fast)s ease-out;
}
switch.sonata-switch:checked { background: %(accent)s; }
switch.sonata-switch > slider {
  min-width: 16px; min-height: 16px; margin: 1px; border-radius: 99px; border: none;
  background: %(knob)s; box-shadow: %(shadow_knob)s;
}
switch.sonata-switch image { opacity: 0; }   /* no I/O glyphs */

/* slider (Big Sur menu slider: thin track, accent fill, white knob) */
scale.sonata-slider { padding: 6px 0; min-width: 160px; }
scale.sonata-slider trough { min-height: 4px; border-radius: 99px; background: %(control_off)s; border: none; }
scale.sonata-slider highlight { border-radius: 99px; background: %(accent_ink)s; border: none; }
scale.sonata-slider slider { min-width: 18px; min-height: 18px; margin: -7px; border-radius: 99px;
  border: none; background: #ffffff; box-shadow: 0 0 0 0.5px rgba(0,0,0,0.16), 0 0 2px rgba(0,0,0,0.22); }

/* module slider (Control Center: thick capsule, white fill, knob at the end) */
scale.sonata-module-slider { padding: 0; min-width: 240px; }
scale.sonata-module-slider trough { min-height: 22px; border-radius: 99px; border: none;
  background: %(module_track)s; box-shadow: inset 0 0 0 0.5px %(separator)s; }
/* GTK ends the fill at the knob's centre; Big Sur's fill runs under the whole
   knob, so the capsule reads as one piece: extend it by the knob's radius. */
scale.sonata-module-slider highlight { min-height: 22px; border-radius: 99px; border: none; background: %(module_fill)s;
  margin-right: -11px; }
scale.sonata-module-slider slider { min-width: 22px; min-height: 22px; margin: 0; border-radius: 99px; border: none;
  background: #ffffff; box-shadow: 0 0 0 0.5px rgba(0,0,0,0.14), 0 0 3px rgba(0,0,0,0.22); }   /* even: no downward drop */
scale.sonata-module-slider:disabled { opacity: 0.45; }     /* dimmed as a whole: no see-through knob */

/* text field (Big Sur: white well, hairline, accent focus ring) */
entry.sonata-field, passwordentry.sonata-field {
  min-height: %(control_h)s; padding: 0 7px; border-radius: %(r_button)s; border: none;
  font-family: %(font)s; font-size: %(text_body)s; color: %(label)s; background: %(content_bg)s;
  box-shadow: inset 0 0 0 0.5px %(hairline)s, inset 0 0.5px 0 alpha(#000, 0.06);
  outline: none; transition: box-shadow %(t_fast)s ease-out;
}
entry.sonata-field:focus-within, passwordentry.sonata-field:focus-within {
  box-shadow: inset 0 0 0 0.5px %(hairline)s, 0 0 0 3px alpha(%(accent)s, 0.45); }
entry.sonata-field > text > placeholder, passwordentry.sonata-field > text > placeholder {
  color: %(label_tertiary)s; }
entry.sonata-field:disabled, passwordentry.sonata-field:disabled { color: %(label_tertiary)s; }
passwordentry.sonata-field > image { color: %(label_secondary)s; }

/* text area: a rounded field that grows with its text (message composers) */
.sonata-text-area { background: %(control_bg)s; border-radius: 18px; padding: 3px 4px 3px 14px;
  box-shadow: inset 0 0 0 0.5px %(hairline)s, %(shadow_control)s; transition: box-shadow %(t_fast)s ease-out; }
.sonata-text-area:focus-within { box-shadow: inset 0 0 0 0.5px %(hairline)s, 0 0 0 3px alpha(%(accent)s, 0.35); }
.sonata-text-area textview, .sonata-text-area textview text { background: none; color: %(label)s;
  font-family: %(font)s; font-size: %(text_body)s; }
.sonata-text-area .sonata-placeholder { color: %(label_tertiary)s; }
/* round accent button at the end of a text area (Send) */
.sonata-text-area button.sonata-round { min-width: 28px; min-height: 28px; padding: 0; border-radius: 99px;
  border: none; box-shadow: none; background: %(accent)s; color: %(label_on_accent)s;
  transition: background-color %(t_fast)s, opacity %(t_fast)s; }
.sonata-text-area button.sonata-round:disabled { opacity: 0.35; }
.sonata-text-area button.sonata-round:active { filter: brightness(0.85); transition: filter %(t_press)s; }

.seg { background: alpha(%(label)s, 0.08); border-radius: 9px; padding: 2px; }
.seg button { min-height: 20px; min-width: 0; padding: 0 6px; border-radius: 7px; background: none;
  box-shadow: none; border: none; color: %(label)s; font-size: 12px; font-weight: 600;
  transition: background-color %(t_fast)s, color %(t_fast)s; }
.seg button:hover { background: alpha(%(label)s, 0.08); }
.seg button.on, .seg button.on:hover { background: %(accent)s; color: %(label_on_accent)s; }
.seg:disabled { opacity: 0.45; }
/* plain: a toolbar's tabs (Clock: Alarms | Stopwatch | Timers) -- the chosen
   one raised in the control colour, like macOS, not in the accent */
.seg.plain button { padding: 0 12px; font-weight: 500; }
.seg.plain button.on, .seg.plain button.on:hover { background: %(control_bg)s; color: %(label)s;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.18), 0 0 0 0.5px rgba(0, 0, 0, 0.06); }
/* circle_button: Clock's Start / Stop / Lap (macOS Clock) */
.sonata-circle { min-width: 72px; min-height: 72px; padding: 0; border-radius: 999px; border: none;
  font-size: 15px; font-weight: 500; box-shadow: inset 0 0 0 2px %(content_bg)s;
  transition: background-color %(t_fast)s, color %(t_fast)s, opacity %(t_fast)s; }
.sonata-circle:active { opacity: 0.75; }
.sonata-circle:disabled { opacity: 0.4; }
.sonata-circle.grey { background: alpha(%(label)s, 0.10); color: %(label)s; }
.sonata-circle.green { background: alpha(%(sys_green)s, 0.22); color: shade(%(sys_green)s, 0.8); }
.sonata-circle.red { background: alpha(%(sys_red)s, 0.20); color: %(sys_red)s; }
.sonata-circle.orange { background: alpha(%(sys_orange)s, 0.22); color: shade(%(sys_orange)s, 0.85); }

ui/menu.py.css:
popover.menu { background: none; box-shadow: none; padding: 0; }
popover.menu > contents {
  padding: 5px; border-radius: %(r_menu)s; min-width: %(menu_min_w)s;
  font-family: %(font)s; font-size: %(text_body)s;
  color: %(label)s; background-color: %(panel_material)s;
  box-shadow: 0 0 0 0.5px %(hairline)s, inset 0 0 0 0.5px %(highlight)s, %(shadow_menu)s;
}
/* every menu -- menu bar, right-click, and their nested submenus (which
   don't inherit our classes) -- is the same glass (Vini) */
popover.menu modelbutton {
  min-height: %(control_h)s; padding: 0 10px; border-radius: %(r_menu_row)s;
  color: inherit; background: none;
}
popover.menu modelbutton:hover, popover.menu modelbutton:selected,
popover.menu modelbutton:focus-visible {
  background-color: %(accent_selected)s; color: %(label_on_accent)s;
}
/* the pointer left the menu: no row stays highlighted (macOS); the
   keyboard brings the selection back */
popover.menu.pointer-out modelbutton:selected:not(:hover):not(:focus-visible) {
  background: none; color: inherit; }
popover.menu modelbutton:disabled { color: %(label_tertiary)s; }
/* GTK's own check/radio sits before the text and pushes every row's text
   right (its column is shared): hidden, with no width -- _checks_after_text
   shows a check after the text instead (Vini) */
popover.menu modelbutton check, popover.menu modelbutton radio { min-width: 0; min-height: 0; margin: 0;
  padding: 0; border: none; background: none; box-shadow: none; opacity: 0; -gtk-icon-size: 0; }
popover.menu modelbutton image.sonata-menu-check { -gtk-icon-size: 12px; margin-left: 12px; color: inherit; }
popover.menu modelbutton arrow { -gtk-icon-size: 12px; color: inherit; }
popover.menu separator { margin: 5px 10px; min-height: 1px; background-color: %(separator)s; }
/* the menu's (never shown) scrollbar has a minimum length: a one-item menu
   was that tall, with a gap under the item (Vini) */
popover.menu scrollbar, popover.menu scrollbar range, popover.menu scrollbar trough,
popover.menu scrollbar slider { min-height: 0; min-width: 0; margin: 0; padding: 0; border: none; }
/* pop-up buttons' lists (Gtk.DropDown: Settings, Control Center's sound
   devices...) are the same glass menu: no opaque list behind the rows */
popover.menu listview, popover.menu listview.view, popover.menu scrolledwindow { background: none; }
popover.menu listview > row { min-height: %(control_h)s; padding: 0 10px; margin: 0; border-radius: %(r_menu_row)s;
  color: inherit; background: none; }
popover.menu listview > row:hover, popover.menu listview > row:selected:hover,
popover.menu listview > row:focus-visible { background-color: %(accent_selected)s; color: %(label_on_accent)s; }
popover.menu listview > row:selected { background: none; }
/* a hairline between the options (Vini), inset like the menus' separators;
   gone under the highlighted row and the one after it */
popover.menu listview > row:not(:first-child) {
  background-image: linear-gradient(%(separator)s, %(separator)s);
  background-size: calc(100%% - 20px) 1px; background-position: center top; background-repeat: no-repeat; }
popover.menu listview > row:hover, popover.menu listview > row:hover + row,
popover.menu listview > row:focus-visible, popover.menu listview > row:focus-visible + row { background-image: none; }
popover.menu listview > row image { -gtk-icon-size: 12px; color: inherit; }
/* rows with a small x (Dock: an app's windows) */
popover.menu .sonata-menu-row { min-height: %(control_h)s; border-radius: %(r_menu_row)s; padding: 0 4px 0 0; }
popover.menu .sonata-menu-row:hover { background-color: %(accent_selected)s; color: %(label_on_accent)s; }
popover.menu .sonata-menu-row-label { background: none; border: none; box-shadow: none; padding: 0 10px;
  min-height: %(control_h)s; color: inherit; font-weight: normal; }
popover.menu .sonata-menu-x { min-width: 16px; min-height: 16px; padding: 0; border-radius: 99px; border: none;
  background: none; box-shadow: none; color: inherit; opacity: 0.55; -gtk-icon-size: 10px; }
popover.menu .sonata-menu-x:hover { opacity: 1; background: alpha(currentColor, 0.18); }

ui/window.py.css:
/* macOS-style window controls ("traffic lights"). Every state is spelled out
   and the provider is loaded above USER priority, so a user GTK theme (e.g. a
   macOS-look theme in ~/.config/gtk-4.0) can't repaint them grey on
   hover/press/focus. */
/* Size, spacing and place: tokens.FRAME (the same for every window: Sonata's,
   pixdecor's, other GTK 4 apps'). */
.traffic { margin-left: %(tl_margin_left)s; margin-top: %(tl_margin_top)s; }
headerbar .traffic { margin-left: %(tl_hb_left)s; margin-top: %(tl_hb_top)s; }   /* headerbar adds its own padding */
/* on the right (Settings > Appearance): the same room from the right edge;
   it kept the left one's margin, and the right edge got whatever its
   container left */
.traffic.traffic-right { margin-left: 0; margin-right: %(tl_margin_left)s; }
headerbar .traffic.traffic-right { margin-left: 0; margin-right: %(tl_hb_left)s; }
/* the dots to reorder (Settings > Appearance > Button order): in a row, not a title bar */
.traffic.traffic-order { margin: 0; }
/* The dots are the same pictures pixdecor draws on other apps' title bars
   (tools/gen-decor.py), so every window looks and hovers alike: the glyph
   fades in on the button under the pointer. */
.traffic button,
.traffic button:hover,
.traffic button:active,
.traffic button:checked,
.traffic button:focus,
.traffic button:focus-visible,
.traffic button:backdrop {
  min-width: %(tl_dot)s; min-height: %(tl_dot)s; padding: 0; margin: 0 %(tl_half_gap)s;
  border: none; border-radius: 999px; outline: none; box-shadow: none; text-shadow: none;
  background-color: transparent; background-repeat: no-repeat; background-position: center;
  background-size: %(tl_dot)s %(tl_dot)s;
  transition: background-image 150ms ease;
}
.traffic button.tl-close { background-image: -gtk-icontheme("sonata-tl-close"); }
.traffic button.tl-close:hover { background-image: -gtk-icontheme("sonata-tl-close-hover"); }
.traffic button.tl-min { background-image: -gtk-icontheme("sonata-tl-minimize"); }
.traffic button.tl-min:hover { background-image: -gtk-icontheme("sonata-tl-minimize-hover"); }
.traffic button.tl-zoom { background-image: -gtk-icontheme("sonata-tl-maximize"); }
.traffic button.tl-zoom:hover { background-image: -gtk-icontheme("sonata-tl-maximize-hover"); }
.traffic button.tl-disabled, .traffic button.tl-disabled:hover, .traffic button.tl-disabled:backdrop {
  background-image: none; background-color: %(tl_disabled)s; box-shadow: inset 0 0 0 0.5px rgba(0,0,0,.18); }
.traffic button:active { filter: brightness(0.85); }
.traffic button label { color: transparent; font-size: 1px; padding: 0; margin: 0; }

.sonata-sidebar { background: %(sidebar_material)s; }
window.sonata-glass { background: transparent; }
/* GTK's own drop-target outline (Adwaita paints it orange): Sonata marks
   drop targets itself (.drop-target / .drop-hover / .folder-target) */
*:drop(active), *:drop(active):focus { box-shadow: none; outline: none; }
/* small utility windows (About, Get Info): all glass, the Dock's material */
window.sonata-glass-window { background: %(panel_material)s; }

window.sonata-window.csd { border-radius: %(r_window)s;
  box-shadow: %(window_shadow)s, 0 0 0 0.5px rgba(0, 0, 0, 0.40),
              inset 0 0 0 0.5px %(highlight)s; }
window.sonata-window.csd:backdrop { box-shadow: %(window_shadow_backdrop)s, 0 0 0 0.5px rgba(0, 0, 0, 0.30); }
/* maximized/tiled: a hairline only for windows drawing their own frame; under
   the compositor's title bar it drew a dark line between the glass title
   bar and a glass toolbar (Preview) */
window.sonata-window.csd.maximized, window.sonata-window.csd.tiled,
window.sonata-window.csd.tiled-top, window.sonata-window.csd.tiled-left, window.sonata-window.csd.tiled-right,
window.sonata-window.csd.tiled-bottom { box-shadow: 0 0 0 0.5px rgba(0, 0, 0, 0.40), inset 0 0 0 0.5px %(highlight)s; }
window.sonata-window:not(.csd) { box-shadow: none; }
/* the divider between a sidebar and the content: opaque (the window itself
   is see-through for the glass toolbar, so a bare divider showed the
   wallpaper through a 1 px gap) */
window.sonata-window paned:not(.vertical) > separator { min-width: 1px; background: %(content_bg)s;
  box-shadow: inset 1px 0 %(separator)s; }
window.sonata-window paned.vertical > separator { min-height: 1px; background: %(content_bg)s;
  box-shadow: inset 0 1px %(separator)s; }
window.sonata-window.fullscreen { border-radius: 0; box-shadow: none; }

window.sonata-unified { background: transparent; }
.sonata-toolbar { min-height: 34px; padding: 2px 8px 0 8px; background: %(titlebar_bg)s;
  box-shadow: inset 0 -1px %(separator)s; }
window:backdrop .sonata-toolbar { background: %(titlebar_bg_inactive)s; }
/* pixdecor's title bar reaches under the window's top: 1 px, 5 px when
 * maximized. Those rows of the toolbar stay see-through, so the title bar's
 * glass shows there alone -- painted twice, the glass turned into a dark
 * band (the compositor's seam fix could miss it, maximized). */
window.sonata-unified .sonata-toolbar {
  background: linear-gradient(to bottom, transparent 1px, %(titlebar_bg)s 1px); }
window.sonata-unified:backdrop .sonata-toolbar {
  background: linear-gradient(to bottom, transparent 1px, %(titlebar_bg_inactive)s 1px); }
window.sonata-unified.maximized .sonata-toolbar {
  background: linear-gradient(to bottom, transparent 5px, %(titlebar_bg)s 5px); }
window.sonata-unified.maximized:backdrop .sonata-toolbar {
  background: linear-gradient(to bottom, transparent 5px, %(titlebar_bg_inactive)s 5px); }
.sonata-toolbar button.tool { min-width: 28px; min-height: 26px; padding: 0 6px; border-radius: 6px;
  border: none; background: none; box-shadow: none; color: %(label_secondary)s; }
.sonata-toolbar button.tool:hover { background: %(tool_hover)s; color: %(label)s; }

calculator/window.py.css:
window.sonata-calculator { background: %(calc_bg)s; }
.calc-display { padding: 8px 16px 2px 16px; }
.calc-display label { color: %(calc_display)s; font-family: %(font_display)s; font-weight: 300; }
.calc-keys { padding: 6px 8px 10px 8px; }
button.calc-key { min-width: 48px; min-height: 42px; padding: 0; border-radius: 8px; border: none;
  font-size: 20px; font-weight: 400; box-shadow: none; background: %(calc_key)s; color: %(calc_key_text)s;
  transition: background-color 90ms ease-out, filter 90ms ease-out; }
button.calc-key:hover { filter: brightness(1.08); }
button.calc-key:active, button.calc-key.pressed { filter: brightness(1.35); transition: none; }
button.calc-key.fn { background: %(calc_key_fn)s; font-size: 17px; }
button.calc-key.op { background: %(calc_key_op)s; color: white; font-size: 24px; }
button.calc-key.op.armed { background: white; color: %(calc_key_op)s; }

clock/window.py.css:
window.sonata-clock .ck-main { background: %(content_bg)s; }
.ck-title { font-family: %(font_display)s; font-size: 26px; font-weight: 700; color: %(label)s; padding: 14px 24px 4px 24px; }
.ck-list { background: none; padding: 0 12px 16px 12px; }
.ck-list row { border-radius: 10px; padding: 0; background: none; }
.ck-list row:hover { background: %(tool_hover)s; }
.ck-row { padding: 10px 14px; box-shadow: inset 0 -1px %(separator)s; }
.ck-time { font-family: %(font_display)s; font-size: 40px; font-weight: 300; color: %(label)s; }
.ck-row.off .ck-time, .ck-row.off .ck-sub { color: %(label_tertiary)s; }
.ck-sub { font-size: %(text_body)s; color: %(label_secondary)s; }
.ck-empty { color: %(label_tertiary)s; font-size: %(text_title)s; }
.ck-edit { padding: 12px; }
.ck-edit spinbutton { font-family: %(font_display)s; font-size: 20px; font-weight: 400; min-width: 0; }
.ck-edit spinbutton text { min-width: 0; padding: 2px 0; }
.ck-colon { font-family: %(font_display)s; font-size: 20px; color: %(label)s; }
.ck-day { min-width: 30px; min-height: 30px; padding: 0; border-radius: 99px; font-weight: 600; }
.ck-day:checked { background: %(accent)s; color: white; }

clock/pages.py.css:
.ck-big { font-family: %(font_display)s; font-weight: 200; font-size: 72px; color: %(label)s;
  font-feature-settings: "tnum"; }
.ck-ring-time { font-family: %(font_display)s; font-weight: 200; font-size: 50px; color: %(label)s;
  font-feature-settings: "tnum"; }
.ck-ring-sub { color: %(label_secondary)s; font-size: %(text_body)s; font-feature-settings: "tnum"; }
.ck-laps { background: none; margin: 0 24px 12px 24px; }
.ck-laps row { padding: 8px 2px; box-shadow: inset 0 1px %(separator)s; background: none; }
.ck-laps label { font-size: 14px; color: %(label)s; font-feature-settings: "tnum"; }
.ck-laps .best label { color: %(sys_green)s; }
.ck-laps .worst label { color: %(sys_red)s; }
.ck-chip { border-radius: 99px; padding: 3px 8px; min-height: 22px; background: alpha(%(label)s, 0.07);
  border: none; box-shadow: none; color: %(label)s; font-size: 12px; }
.ck-chip:hover { background: alpha(%(label)s, 0.13); }
.ck-pick spinbutton { font-family: %(font_display)s; font-size: 34px; font-weight: 300; min-width: 0;
  color: %(label)s; }
.ck-pick spinbutton text { min-width: 0; padding: 2px 0; }
.ck-pick .ck-unit { color: %(label_secondary)s; font-size: %(text_small)s; }
